                }
            }

            ds.bankReputation = Math.max(0, Math.min(100, ds.bankReputation + reputationChange));
            ds.totalRevenue = Math.round((ds.totalRevenue + periodRevenue) * 10) / 10;
            ds.riskExposure = Math.max(0, Math.round((ds.riskExposure + riskChange) * 10) / 10);

            ds.reputationHistory.push(ds.bankReputation);
            ds.revenueHistory.push(ds.totalRevenue);
            ds.riskHistory.push(ds.riskExposure);
            ds.periodRevenueHistory.push(Math.round(periodRevenue * 10) / 10);

            // platform score: same verdict inputs as getPerformanceSummary (reputation 75 plus summed changes, summed rounded period revenue, current risk)
            // and the same Excellent, Good, Adequate, Needs Improvement rules, mapped to bands 85-100, 70-84, 50-69 and 0-49,
            // with the position inside a band set by the weakest progress toward the next band thresholds
            ds.eqilRepChangeSum = (ds.eqilRepChangeSum || 0) + reputationChange;
            ds.eqilRevenueSum = (ds.eqilRevenueSum || 0) + (Math.round(periodRevenue * 10) / 10);
            var eqRep = 75 + ds.eqilRepChangeSum;
            var eqRev = ds.eqilRevenueSum;
            var eqRisk = ds.riskExposure;
            var eqClamp = function(v) { return Math.max(0, Math.min(1, v)); };
            var eqScore;
            if (eqRep >= 80 && eqRev >= 15 && eqRisk < 20) {
                eqScore = 85 + Math.round(15 * Math.min(eqClamp((eqRep - 80) / 20), eqClamp((eqRev - 15) / 10), eqClamp((20 - eqRisk) / 20)));
            } else if (eqRep >= 65 && eqRev >= 10) {
                eqScore = 70 + Math.round(14 * Math.min(eqClamp((eqRep - 65) / 15), eqClamp((eqRev - 10) / 5), eqClamp((40 - eqRisk) / 20)));
            } else if (eqRep >= 50 && eqRev >= 5) {
                eqScore = 50 + Math.round(19 * Math.min(eqClamp((eqRep - 50) / 15), eqClamp((eqRev - 5) / 5)));
            } else {
                eqScore = Math.round(49 * Math.min(eqClamp(eqRep / 50), eqClamp(eqRev / 5)));
            }
            ds.performance = Object.assign({}, ds.performance || {}, { overallScore: Math.max(0, Math.min(100, eqScore)) });

            /* v1.1.0: racy setTimeout removed (rendered period N+2 after the synchronous increment). Briefing/panels refresh on the real 'period:submitted' event wired in setupUI. */

            return {
                period: period,
                roundLabel: 'R' + period,
                keyDecision: keyDecision,
                periodRevenue: Math.round(periodRevenue * 10) / 10,
                reputationChange: reputationChange,
                riskChange: Math.round(riskChange * 10) / 10,
                totalRevenue: ds.totalRevenue,
                bankReputation: ds.bankReputation,
                riskExposure: ds.riskExposure,
                activeMandates: ds.activeMandates
            };
        }

