        getPerformanceSummary(history) {
            if (!history.length) return {};
            var totalRev = 0;
            var repChanges = 0;
            for (var i = 0; i < history.length; i++) {
                if (history[i].results) {
                    totalRev += (history[i].results.periodRevenue || 0);
                    repChanges += (history[i].results.reputationChange || 0);
                }
            }
            var finalRep = 75 + repChanges;
            var lastEntry = history[history.length - 1];
            var finalRisk = lastEntry.results ? lastEntry.results.riskExposure : 0;

            var t = function(k) { return window.mySimulation.t(k); };
            var perfKey = 'needs_improvement';
            if (finalRep >= 80 && totalRev >= 15 && finalRisk < 20) perfKey = 'excellent';
            else if (finalRep >= 65 && totalRev >= 10) perfKey = 'good';
            else if (finalRep >= 50 && totalRev >= 5) perfKey = 'adequate';
            var performance = t('perf_' + perfKey);

            var insights = [];
            if (finalRep >= 85) insights.push(t('insight_rep_high'));
            if (finalRep < 50) insights.push(t('insight_rep_low'));
            if (totalRev >= 20) insights.push(t('insight_rev_high'));
            if (totalRev < 5) insights.push(t('insight_rev_low'));
            if (finalRisk > 30) insights.push(t('insight_risk_high'));
            if (finalRisk <= 10 && totalRev >= 10) insights.push(t('insight_conservative'));

            return {
                totalRevenue: Math.round(totalRev * 10) / 10,
                finalReputation: Math.round(finalRep),
                riskExposure: Math.round(finalRisk * 10) / 10,
                performance: performance,
                performanceKey: perfKey,
                performanceLabel: performance,
                insights: insights
            };
        }

        getHint(state, results) {
            if (results.reputationChange < -5) return window.mySimulation.t('hint_reputation_drop');
            if (state.domainState.riskExposure > 25) return window.mySimulation.t('hint_high_risk');
            if (results.periodRevenue < 0) return window.mySimulation.t('hint_negative_revenue');
            if (state.domainState.bankReputation >= 85) return window.mySimulation.t('hint_strong_reputation');
            return null;
        }

